    if (aoStatutFiltres.length > 0) items = items.filter(a => aoStatutFiltres.includes(a.statut));
    const field = aoGroupBy;
    const groups = {};
    items.forEach(ao => { const key = ao[field] || 'Non défini'; if (!groups[key]) groups[key] = []; groups[key].push(ao); });
