              const filChantiers = chantiers.filter(c => c.filialeId === fil.id);
              const filEmps = getEmployesFiliale(fil.id);
              const filChantiersActifs = filChantiers.filter(c => c.statut === 'En cours' || c.statut === 'Planifié');
